package com.campus.service.dto;

import com.campus.service.entity.Category;
import com.campus.service.entity.Priority;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

/**
 * ============================================================
 * DTO: ServiceRequestDTO
 * ============================================================
 *
 * Used when a CLIENT SENDS data to CREATE or UPDATE a service request.
 *
 * This DTO does NOT include:
 * - id        (auto-generated by database)
 * - status    (defaults to PENDING, changed via status endpoint)
 * - createdAt (auto-set by @PrePersist)
 * - updatedAt (auto-set by @PreUpdate)
 * - technician (assigned via separate assign endpoint)
 *
 * This is a good example of how DTOs differ from Entities:
 * The Entity has 11 fields, but the client only sends 5 fields
 * when creating a request. The DTO enforces this contract.
 *
 * INTERVIEW Q: "Why have separate DTOs for request and response?"
 * A: "Because the data a client SENDS is different from what they
 *     RECEIVE. When creating a request, the client sends title,
 *     description, category, priority, location, and studentId.
 *     But the response includes additional fields like id, status,
 *     timestamps, student name, and technician details that the
 *     server generates."
 */
public class ServiceRequestDTO {

    @NotBlank(message = "Title is required")
    private String title;

    @NotBlank(message = "Description is required")
    private String description;

    /**
     * @NotNull is used instead of @NotBlank because Category is an enum,
     * not a String. @NotBlank only works with String types.
     */
    @NotNull(message = "Category is required")
    private Category category;

    @NotNull(message = "Priority is required")
    private Priority priority;

    @NotBlank(message = "Location is required")
    private String location;

    /**
     * The ID of the student creating this request.
     * We use the student's ID (not the full Student object) because:
     * 1. The client only needs to send a simple number, not the full student data.
     * 2. The Service layer will look up the actual Student entity by this ID.
     * 3. It keeps the API simple and lightweight.
     */
    @NotNull(message = "Student ID is required")
    private Long studentId;

    // ==========================================
    // CONSTRUCTORS
    // ==========================================

    public ServiceRequestDTO() {
    }

    public ServiceRequestDTO(String title, String description, Category category,
                             Priority priority, String location, Long studentId) {
        this.title = title;
        this.description = description;
        this.category = category;
        this.priority = priority;
        this.location = location;
        this.studentId = studentId;
    }

    // ==========================================
    // GETTERS AND SETTERS
    // ==========================================

    public String getTitle() {
        return title;
    }

    public void setTitle(String title) {
        this.title = title;
    }

    public String getDescription() {
        return description;
    }

    public void setDescription(String description) {
        this.description = description;
    }

    public Category getCategory() {
        return category;
    }

    public void setCategory(Category category) {
        this.category = category;
    }

    public Priority getPriority() {
        return priority;
    }

    public void setPriority(Priority priority) {
        this.priority = priority;
    }

    public String getLocation() {
        return location;
    }

    public void setLocation(String location) {
        this.location = location;
    }

    public Long getStudentId() {
        return studentId;
    }

    public void setStudentId(Long studentId) {
        this.studentId = studentId;
    }
}